-- Run in Supabase SQL Editor. Review policies and test with non-production accounts first.
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'visitor' check(role in ('super_admin','school_admin','teacher','student','parent','visitor')), created_at timestamptz default now());
create table if not exists public.notices(id bigint generated always as identity primary key,title text not null,body text not null,published boolean default false,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.community_posts(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id),caption text,storage_path text not null,mime_type text,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.notices enable row level security; alter table public.community_posts enable row level security;
create or replace function public.current_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
drop policy if exists "profiles read own" on public.profiles; create policy "profiles read own" on public.profiles for select to authenticated using(id=auth.uid() or public.current_role() in ('super_admin','school_admin'));
drop policy if exists "notices public read published" on public.notices; create policy "notices public read published" on public.notices for select using(published=true or (auth.uid() is not null and public.current_role() in ('super_admin','school_admin')));
drop policy if exists "admins manage notices" on public.notices; create policy "admins manage notices" on public.notices for all to authenticated using(public.current_role() in ('super_admin','school_admin')) with check(public.current_role() in ('super_admin','school_admin'));
drop policy if exists "users create own posts" on public.community_posts; create policy "users create own posts" on public.community_posts for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "users see own and approved posts" on public.community_posts; create policy "users see own and approved posts" on public.community_posts for select to authenticated using(user_id=auth.uid() or status='approved' or public.current_role() in ('super_admin','school_admin'));
drop policy if exists "admins moderate posts" on public.community_posts; create policy "admins moderate posts" on public.community_posts for update to authenticated using(public.current_role() in ('super_admin','school_admin')) with check(public.current_role() in ('super_admin','school_admin'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('school-community','school-community',false,52428800,array['image/*','video/*','audio/*','application/pdf','application/zip','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','text/plain']) on conflict(id) do nothing;
create policy "authenticated upload own folder" on storage.objects for insert to authenticated with check(bucket_id='school-community' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "owner and admins read files" on storage.objects for select to authenticated using(bucket_id='school-community' and ((storage.foldername(name))[1]=auth.uid()::text or public.current_role() in ('super_admin','school_admin')));
